import {icons,items,serviceCatalog,initialProfile,DEMO_CODE,demoIdentity} from './data.js';
import {EMBEDDED_PDF_PREVIEW} from './pdf-assets.js';
import {createDemoPdfUrl} from './pdf.js';
import {createDemoRepository,PROFILE_KEY,PLAN_KEY} from './storage.js';
(()=>{
 'use strict';
 const previewMode = document.documentElement.classList.contains('preview-tools');
 const icon=(name,size=20)=>`<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.info}</svg>`;
 const pickService=id=>serviceCatalog.find(item=>item.id===id)||serviceCatalog[0];
 const escapeAttribute=s=>String(s).replace(/[&"<>]/g,ch=>({'&':'&amp;','"':'&quot;','<':'&lt;','>':'&gt;'}[ch]));
 const demoRepository=createDemoRepository();
 const savedDemo=demoRepository.load();
 const savedPlan=demoRepository.loadPlan();
 const state={view:'today',selected:'mobility',quizChoice:null,feedback:null,preview:'auto',large:demoRepository.loadLarge(),read:{},published:savedPlan.published,version:savedPlan.version,planChanged:savedPlan.planChanged,caregiver:false,helpSearchOpen:false,helpQuery:'',supportSelected:'hospital',authenticated:previewMode,codeVerified:false,loginCode:'',loginError:'',profile:{...savedDemo.profile},profileDraft:null,editing:false,modal:null,notice:'',transferStatus:savedDemo.lastRequest?.revision===savedDemo.revision?'requested':'none',lastRequest:savedDemo.lastRequest,savedRevision:savedDemo.revision,pdfOpen:false,pdfUrl:null,pdfPreviewError:false,transferConsent:false};
 const app=document.querySelector('#app'),stage=document.querySelector('#stage');
 let overlayReturnFocus=null;
 function closePdf(){if(state.pdfUrl){try{URL.revokeObjectURL(state.pdfUrl)}catch{}}state.pdfUrl=null;state.pdfOpen=false;}
 function closeOverlay(){state.modal=null;state.transferConsent=false;closePdf();render();const target=document.querySelector(overlayReturnFocus||'#main-content');if(target&&!target.disabled)target.focus();else focusMain();overlayReturnFocus=null;}
 if(demoRepository.failed)state.notice='저장된 정보를 확인할 수 없어 덮어쓰기를 중지했어요. 기존 데이터를 보관한 뒤 브라우저 저장 상태를 확인해 주세요.';
 const task=id=>items.find(x=>x.id===id)||items[0];
 const isPatientView=()=>state.view!=='clinician';
 const key=(v)=>v==='detail'||v==='quiz'? 'today':v==='support'?'help':v==='overview'?'today':v;
 function render(){
  if(!state.authenticated||!state.published){state.modal=null;closePdf();}
  stage.dataset.preview=state.preview;
  document.body.classList.toggle('large-font',state.large);
  document.querySelectorAll('[data-preview]').forEach(b=>{if(b.matches('button'))b.setAttribute('aria-pressed',String(b.dataset.preview===state.preview))});
  const demoFont=document.querySelector('.devbar [data-action=font]');if(demoFont)demoFont.textContent=state.large?'기본 글자':'글자 크게';
  const k=key(state.view);
  if(!state.authenticated){app.innerHTML=loginScreen();return;}
  let page=state.view==='today'?home():state.view==='detail'?detail():state.view==='quiz'?quiz():state.view==='schedule'?schedule():state.view==='help'?help():state.view==='support'?support():state.view==='overview'?overview():state.view==='profile'?profilePage():(previewMode?clinician():home());
  app.innerHTML=`<div class="app-layout"${state.modal||state.pdfOpen?' inert':''}><aside class="side" aria-label="주요 메뉴"><div class="side-brand"><div class="side-logo">D.</div><div><b>나의 하루</b><small>퇴원 후 관리</small></div></div><div class="side-cap">나의 계획</div>${nav('today','오늘', 'home',k)}${nav('schedule','일정', 'calendar',k)}${nav('help','도움', 'help',k)}${nav('profile','내 정보', 'user',k)}<div class="side-end"><b>가상 퇴원 안내</b><br>의료진이 확인한 계획을<br>환자에게 쉽게 전달합니다.</div></aside><div class="app-body"><header class="topline"><span class="kicker">퇴원 후, 나의 하루</span><div class="meta"><button class="top-profile" data-nav="profile">내 정보</button><button class="top-font" data-action="font" aria-label="글자 크기 전환">${state.large?'글자 기본':'글자 크게'}</button><span class="version-meta">${state.published?(state.planChanged?'변경된 안내 · v'+state.version+'.0':'의료진 확인 · v1.0'):'안내 철회됨'}</span><span class="tiny-pill">가상 환자</span></div></header><main id="main-content" class="main" tabindex="-1">${isPatientView()&&!state.published?blocked():page}</main><nav class="bottom-nav" aria-label="모바일 주요 메뉴">${mobileNav('today','오늘','home',k)}${mobileNav('schedule','일정','calendar',k)}${mobileNav('help','도움','help',k)}</nav></div></div>${state.notice&&state.view!=='profile'?`<div class="toast" role="status">${escapeAttribute(state.notice)}</div>`:''}${state.modal?confirmDialog():''}${state.pdfOpen?pdfViewer():''}`;
  if(state.view==='help'&&state.helpSearchOpen&&state.published)runHelpSearch(state.helpQuery);
 }
 const nav=(v,label,symbol,active)=>`<button class="side-nav" data-nav="${v}" ${active===v?'aria-current="page"':''}>${icon(symbol,21)}${label}</button>`;
 const mobileNav=(v,label,symbol,active)=>`<button data-nav="${v}" ${active===v?'aria-current="page"':''}>${icon(symbol,22)}${label}</button>`;
 const approved=()=>`<div class="updated">${icon('shield',19)}<span>가상 의료진 확인 · 2026.10.20${state.planChanged?' · 새 안내 발행(v'+state.version+'.0)':''}</span></div>`;

 const safeText=v=>escapeAttribute(String(v ?? ''));
 function loginScreen(){return `<main class="login-viewport"><section class="login-panel"><div class="login-mark">D.</div><div class="eyebrow">퇴원 후, 나의 하루 · 데모</div><h1>퇴원 후 필요한 관리를<br>확인해 보세요.</h1><p>실제 환자정보를 입력하거나 조회하지 않는 <b>가상 환자 접속 시연</b>입니다.</p><div class="login-flow"><span>1. 체험용 코드 입력</span><span>2. 가상 환자 안내 보기</span></div><form id="demo-login" class="login-form"><label for="demo-code">체험용 코드 입력</label><input id="demo-code" name="demoCode" type="text" autocapitalize="characters" autocomplete="off" spellcheck="false" maxlength="20" value="${safeText(state.loginCode)}" placeholder="체험 코드" required><div class="demo-code">체험용 코드: <strong>CARE2026</strong></div>${state.loginError?`<p class="form-error" role="alert">${safeText(state.loginError)}</p>`:''}<button type="submit" class="primary">가상 환자 안내 시작 ${icon('chev',18)}</button></form><div class="security-note"><b>개인정보 보호 안내</b><p>이 코드는 오직 공개된 <b>가상 환자 한 명</b>의 안내를 보여줍니다. 실제 주민등록번호·이름·생년월일·입원정보를 입력하지 마세요. 실제 서비스에는 별도의 본인인증·병원 기록 연결과 접근권한 검증이 필요합니다.</p></div></section></main>`;}
 function profilePage(){const editing=state.editing;const d=state.profileDraft||state.profile;return `<div class="profile-layout"><div class="eyebrow">가상 계정 · 내 정보</div><h1>내 정보</h1><p class="profile-intro">병원에서 확인한 정보와 변경을 요청할 정보를 구분했어요.</p>${state.notice?`<div class="inline-notice" role="status">${safeText(state.notice)}</div>`:''}<section class="profile-section"><div class="profile-section-head"><h2>병원 등록 정보</h2><span class="profile-tag">읽기 전용 · 가상 자료</span></div><div class="profile-grid"><div><small>성명</small><strong>${demoIdentity.name} (가상)</strong></div><div><small>출생정보</small><strong>${demoIdentity.born}</strong></div><div><small>입원 기간</small><strong>${demoIdentity.admission}</strong></div><div><small>진료기관</small><strong>${demoIdentity.hospital}</strong></div></div><p class="profile-help">진료기록·환자 식별정보는 이 화면에서 수정할 수 없어요. 병원 기록이 잘못되었다면 담당 기관에 정정 요청이 필요합니다.</p></section><section class="profile-section"><div class="profile-section-head"><h2>연락·주소 정보</h2><span class="profile-tag">가상 정보 · 수정 가능</span></div>${editing?`<form id="profile-form" class="profile-form"><label for="address">주소</label><input id="address" name="address" data-profile-field="address" maxlength="120" value="${safeText(d.address)}" required><label for="contact">연락처</label><input id="contact" name="contact" data-profile-field="contact" maxlength="50" value="${safeText(d.contact)}" required><p class="profile-help">데모 데이터만 사용하세요. 수정한 가상 정보는 브라우저에 임시 보관됩니다. 서버나 병원 자료와는 연동되지 않습니다.</p><div class="profile-actions"><button class="primary" type="submit">수정 내용 저장</button><button class="link-soft" type="button" data-action="edit-cancel">취소</button></div></form>`:`<div class="profile-grid"><div><small>등록된 주소</small><strong>${safeText(state.profile.address)}</strong></div><div><small>등록된 연락처</small><strong>${safeText(state.profile.contact)}</strong></div></div><button class="secondary-action" data-action="edit-start">주소·연락처 수정하기 ${icon('chev',17)}</button>`}</section><section class="profile-section transfer-section"><h2>정보 업데이트 요청</h2><p>저장한 가상 주소·연락처의 변경을 기관에 요청하는 과정입니다. 현재는 요청 내역만 이 브라우저에 기록하며 실제 기관에는 보내지지 않습니다.</p><div class="transfer-status">${state.transferStatus==='requested'?`모의 요청 ${safeText(state.lastRequest?.requestId||'')} · 저장된 변경 ${state.savedRevision}차 · 실제 기관 전송 없음`:'저장 후 기관 전송 요청을 별도로 선택할 수 있어요.'}</div><button type="button" class="primary" data-action="transfer-open" ${state.editing||!state.savedRevision||state.transferStatus==='requested'?'disabled':''}>정보 업데이트 전송 요청 ${icon('chev',18)}</button><p class="profile-help">실제 서비스에는 기관별 수신 대상 확인, 정보 제공 동의, 환자 본인확인, 전송 기록 및 기관의 수락·반려 상태가 별도로 필요합니다.</p></section><button type="button" class="logout-btn" data-action="logout">가상 계정에서 나가기</button></div>`;}
 function confirmDialog(){const isSave=state.modal==='save';return `<div class="modal-backdrop" data-modal-backdrop="true"><section class="modal-panel" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">${isSave?'수정한 정보를 저장할까요?':'연관 기관에 변경 요청을 보낼까요?'}</h2>${isSave?`<p>가상 주소·연락처의 변경 내용을 이 브라우저에 저장합니다. 병원 등록 정보는 자동으로 바뀌지 않아요.</p><div class="modal-diff"><small>변경할 주소</small><strong>${safeText(state.profileDraft?.address||'')}</strong><small>변경할 연락처</small><strong>${safeText(state.profileDraft?.contact||'')}</strong></div>`:`<p>가상 병원 퇴원관리팀과 지역 돌봄 담당기관으로 보낼 <b>요청 단계만</b> 시연합니다. 외부 서버로 데이터가 전송되지 않습니다.</p><label class="consent-row"><input id="transfer-consent" type="checkbox" ${state.transferConsent?'checked':''}><span>주소·연락처의 변경 요청을 지정 기관에 제공하는 시연에 동의합니다.</span></label>`}<div class="modal-actions"><button class="link-soft" data-action="modal-cancel">취소</button><button class="primary" data-action="${isSave?'modal-save':'modal-transfer'}">${isSave?'변경사항 저장':'모의 전송 요청 기록'}</button></div></section></div>`;}
 function pdfViewer(){const pdf=state.pdfUrl||'';return `<div class="pdf-backdrop"><section class="pdf-panel" role="dialog" aria-modal="true" aria-labelledby="pdf-title"><header class="pdf-panel-header"><div><small>첨부된 자료 · 시연용</small><h2 id="pdf-title">보행 보조기 안내문 (PDF)</h2></div><button type="button" class="close-pdf" data-action="pdf-close">닫기 ×</button></header><div class="pdf-fallback"><b>첨부자료 미리보기</b> PDF 첫 페이지를 화면에서 읽을 수 있어요. 원본은 아래에서 열거나 저장하세요.</div><div class="pdf-image-scroll">${state.pdfPreviewError?'<p role="status">PDF 미리보기를 표시하지 못했어요. 아래에서 PDF 원본을 열거나 저장해 주세요.</p>':`<img class="pdf-image" src="${EMBEDDED_PDF_PREVIEW}" alt="시연용 보행 보조기 안내문 PDF 1쪽 미리보기">`}</div><div class="pdf-actions"><a target="_blank" rel="noopener" class="secondary-action" href="${pdf}">PDF 새 창으로 열기</a><a class="secondary-action" href="${pdf}" download="보행_보조기_안내_시연용.pdf">PDF 파일 저장</a></div><p class="profile-help">실제 치료지침이 아닌 가상 교육자료입니다. PDF 원본은 이 시안의 내부 데이터로 제공되며, ZIP에도 별도로 포함돼 있습니다.</p></section></div>`;}
 function home(){return `<div class="page-head"><div class="eyebrow">퇴원 후 3일째 · 2026년 10월 20일 (가상)</div><section class="hero-panel"><span class="hero-chip">퇴원 후 필요한 관리를 안내합니다.</span><h1 class="hero-title">이정희님,<br><em>오늘의 관리 계획</em></h1><p class="sublead">지금 필요한 일부터 모았어요.</p>${approved()}</section></div><div class="content-grid"><section aria-labelledby="today-tasks"><div class="section-top"><h2 class="section-title" id="today-tasks">오늘 확인할 안내</h2></div><div class="tasks">${items.map(x=>`<button class="task" data-detail="${x.id}"><span class="task-number">${x.number}</span><span class="task-content"><b>${x.title}</b><small>${x.short}</small>${state.read[x.id]?'<span class="task-tag done">확인 문제 참여</span>':''}</span><span class="task-chevron">${icon('chev',20)}</span></button>`).join('')}</div></section><aside class="aside-stack"><section class="appointment"><div class="block-overline">가장 가까운 진료</div><div class="date-line"><span class="date-big">10.27</span><span class="date-unit">화요일 · 오전 10:30</span></div><h3 class="ap-title">정형외과 외래</h3><p class="ap-desc">가상병원 본관 2층<br>실제 병원 예약과는 연결되지 않아요.</p><div class="ap-state">${icon('check',16)}가상 예약 확정 · 시연용</div><div class="ap-bottom"><button class="text-action" data-nav="schedule">일정 전체 보기 ${icon('chev',15)}</button></div></section><section class="insight-strip"><h3>더 자세한 설명이 필요하신가요?</h3><p>가족이나 의료인과 함께 볼 수 있도록 전체 계획과 현재 상태를 조금 더 자세히 확인할 수 있어요.</p><button class="text-action" data-nav="overview">계획 전체와 상태 보기 ${icon('chev',15)}</button></section></aside></div><section class="home-help-wide" aria-labelledby="home-help-title"><div class="home-help-heading"><div><h2 id="home-help-title">도움이 필요할 때</h2><p>필요한 안내를 선택하거나 다른 서비스를 찾아보세요.</p></div><button class="home-help-main" type="button" data-nav="help">서비스 전체 보기 ${icon('chev',18)}</button></div><div class="home-help-shortcuts" aria-label="자주 찾는 도움"><button type="button" data-service-id="hospital">${icon('help',19)}병원 문의 ${icon('chev',16)}</button><button type="button" data-service-id="warning">${icon('info',19)}주의사항 ${icon('chev',16)}</button><button type="button" data-service-id="community">${icon('home',19)}돌봄·생활지원 ${icon('chev',16)}</button></div></section><p class="foot-note">이 화면의 모든 정보는 가상 사례입니다. 실제 의료진의 지시·진료 예약을 대신하지 않습니다.</p>`}
 function detail(){const x=task(state.selected);const pdf=x.id==='mobility'&&state.version===1;return `<div class="detail-wrap"><button class="back-button" data-nav="today">${icon('back',19)} 오늘 화면으로</button><div class="detail-heading"><div class="eyebrow">내 퇴원 안내 · ${x.number} / 03</div><h1>${x.title}</h1><p>${x.intro}</p></div><section class="focus-panel"><h2 class="focus-title">먼저 확인할 내용</h2><ol class="steps">${x.steps.map((s,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><div>${s}</div></li>`).join('')}</ol></section><section class="document-panel" aria-label="추가 안내 자료"><div class="document-label">${icon('info',19)} 상세 자료</div><h2 class="document-title">자세한 내용을 확인할까요?</h2><p class="document-desc">짧은 안내로 부족하다면 원문 자료를 함께 살펴보세요.</p>${pdf?`<div class="document-meta">${icon('print',18)} 보행 보조기 안내문 · PDF · 시연용 자료 · 계획 v1.0 예시</div><button class="document-cta" type="button" data-action="pdf-open">앱에서 PDF 확인하기 ${icon('chev',18)}</button><span class="source-link-placeholder">시연용 PDF를 앱 안에서 보거나 저장할 수 있어요.</span>`:`<div class="document-unavailable">${x.id==='mobility'&&state.version>1?'새로운 계획 버전에 연결된 PDF는 아직 없어요. 이전 자료를 최신 지시처럼 보여주지 않습니다.':'현재 첨부된 PDF는 없어요. 필요하면 담당 의료진에게 자료를 요청해 주세요.'}</div>`}</section><div class="note-block">${icon('info',20)}<span>${x.note}</span></div><p class="approval-line">가상 의료진 확인 · 계획 v${state.version}.0 · PDF는 실제 의료 지침이 아닌 시연용 자료입니다.</p><div class="detail-secondary-row"><button class="primary" data-nav="today">오늘 안내로 돌아가기 ${icon('chev',18)}</button><button class="quiz-optional" data-action="quiz-start">${state.read[x.id]?'확인 문제 다시 풀기':'안내 확인 문제 풀어보기 (선택)'} ${icon('chev',17)}</button></div><p class="quiz-explain">확인 문제를 풀지 않아도 모든 안내를 볼 수 있어요.</p></div>`}
 function quiz(){const x=task(state.selected);const chosen=state.quizChoice;const submitted=state.feedback!==null;return `<div class="quiz-container"><button class="back-button" data-action="detail-back">${icon('back',19)} ${x.title}</button><div class="quiz-context">안내 확인 문제 · 1문제</div><h1 class="quiz-title">${x.question}</h1><p class="quiz-expl">짧은 확인 문제예요. 참여는 선택이며, 답변은 실제 건강관리 수행 여부를 뜻하지 않아요.</p><div class="choices" role="group" aria-label="답변 선택">${x.choices.map((choice,i)=>`<button class="choice" data-choice="${i}" aria-pressed="${chosen===i}" ${submitted?'disabled':''}><span class="radio"></span><span>${choice}</span></button>`).join('')}</div>${submitted?`<div class="feedback ${state.feedback==='correct'?'correct':''}" role="status"><b>${state.feedback==='correct'?'안내와 맞는 답을 골랐어요.':'안내 내용을 다시 살펴볼까요?'}</b><p>${x.why}</p></div>`:''}<div class="action-row">${submitted?`<button class="primary" data-action="quiz-done">${state.feedback==='correct'?'오늘 화면으로 돌아가기':'안내 다시 보기'} ${icon('chev',18)}</button>`:`<button class="primary" data-action="quiz-check" ${chosen===null?'disabled':''}>선택한 답 확인하기 ${icon('chev',18)}</button>`}<button class="link-soft" data-nav="help">도움말 보기</button></div></div>`}
 function overview(){return `<div class="overview-layout"><button class="back-button" data-nav="today">${icon('back',19)} 오늘 화면으로</button><div class="overview-head"><div class="eyebrow">가족·의료인과 함께 보는 상세 안내</div><h1>현재 상태와 계획을<br><em>조금 더 자세히</em> 볼 수 있어요.</h1><p>핵심 안내를 먼저 보여주되, 필요할 때는 이동·복약·일정 정보를 묶어서 더 자세히 확인할 수 있도록 구성했어요.</p>${approved()}</div><section class="summary-card"><span class="summary-chip">가상 상세 보기</span><div class="summary-grid"><article class="card"><h3>현재 상태</h3><p>퇴원 후 3일째예요. 보행 보조기 사용, 상처 주변 상태 확인, 예정된 외래 방문 준비가 중요해요.</p><ul><li>오늘 꼭 확인할 안내 3개</li><li>현재 공개 버전 v${state.version}.0</li><li>이전 계획은 조용히 덮어쓰지 않아요</li></ul></article><article class="card"><h3>이동·활동</h3><p>실내 이동 시 보조기 사용 안내를 우선 확인해 주세요. 무리한 활동은 피하고, 안내에서 허용한 범위를 기준으로 움직여요.</p><ul><li>보조기 사용법 다시 보기</li><li>넘어짐 예방 환경 점검</li><li>통증 증가 시 문의 경로 확인</li></ul></article><article class="card"><h3>약·통증 관리</h3><p>현재 시안은 실제 처방을 보여주지 않아요. 퇴원 때 받은 승인 안내를 기준으로 복약 정보를 다시 확인하는 구조예요.</p><ul><li>변경된 약이 있다면 구분해서 표시</li><li>복용 여부가 아니라 안내 확인 중심</li><li>헷갈리면 병원에 문의</li></ul></article><article class="card"><h3>다음 일정과 공유</h3><p>가까운 외래 일정과 아직 확인 중인 일정이 분리되어 보여요. 가족과 함께 볼 때도 같은 흐름으로 확인할 수 있어요.</p><ul><li>정형외과 외래 10월 27일</li><li>추가 재활 일정은 확인 중</li><li>가족용 공유 화면은 추후 설계</li></ul></article></div><p class="micro-note">이 상세 화면은 가족이나 의료인이 환자와 함께 현재 계획을 검토하기 쉽게 만든 시연용 구조예요. 실제 진단·처방·연계를 대신하지 않아요.</p><div class="summary-actions"><button class="primary" data-detail="mobility">보행 안내부터 보기 ${icon('chev',17)}</button><button class="link-soft" data-nav="schedule">일정 화면 보기</button></div></section></div>`}
function schedule(){return `<div class="schedule-layout"><div class="eyebrow">나의 퇴원 후 일정</div><h1 class="hero-title">앞으로의 일정,<br><em>한눈에 확인하세요.</em></h1><p class="sublead">날짜가 확정된 일정과 아직 확인해야 할 일정을 구분했어요.</p>${approved()}<div class="timeline"><article class="event"><div class="event-date">10.27<small>화요일</small></div><div><h3>정형외과 외래 진료</h3><p>오전 10:30 · 가상병원 본관 2층<br>실제 예약과 연결되지 않은 예시예요.</p><span class="state">가상 일정 확정</span></div></article><article class="event"><div class="event-date">확인 중<small>날짜 미정</small></div><div><h3>추가 치료·재활 일정</h3><p>아직 일정이 확인되지 않았어요. 병원에서 일정이 확정된 뒤 안내할 수 있어요.</p><span class="state pending">일정 확인 필요</span></div></article></div><div class="note-block">${icon('info',20)}<span>이 시안은 실제 예약을 생성하거나 변경하지 않아요. 일정이 불분명할 때 임의의 날짜를 채우지 않는 방식을 검증 중이에요.</span></div><button class="text-action" data-nav="today">오늘 할 일로 돌아가기 ${icon('chev',16)}</button></div>`}
 function serviceCard(service){return `<button class="service-card" data-service-id="${service.id}"><span class="service-card-text"><strong>${service.name}</strong><small>${service.summary}</small></span>${icon('chev',20)}</button>`;}
 function help(){const quick=['hospital','warning','mobility','appointment'].map(pickService);const others=serviceCatalog.filter(s=>!quick.some(q=>q.id===s.id));return `<div class="service-page"><div class="eyebrow">퇴원 후 도움 안내</div><h1 class="service-title">필요한 서비스를 선택해 주세요.</h1><p class="service-lead">확인할 내용을 선택하면 다음에 무엇을 해야 하는지 안내해 드립니다.</p><section aria-label="주요 도움 항목" class="services-panel"><div class="service-list">${quick.map(serviceCard).join('')}</div></section><section class="service-search-launch"><button class="search-launch" data-action="toggle-help-search" aria-expanded="${state.helpSearchOpen}" aria-controls="more-help" type="button"><span><strong>다른 도움이 필요하신가요?</strong><small>복약·재활·돌봄서비스 등 다른 항목 검색</small></span>${icon(state.helpSearchOpen?'back':'chev',21)}</button><div class="help-search-body" id="more-help" ${state.helpSearchOpen?'':'hidden'}><label class="service-search-label" for="service-search-input">필요한 도움 검색</label><input class="search-input" id="service-search-input" data-help-search type="search" autocomplete="off" placeholder="예: 복약, 재활, 간병, 보호자" value="${escapeAttribute(state.helpQuery)}"><div class="search-tags" aria-label="추천 검색어">${['복약','재활','간병','보호자','인쇄'].map(t=>`<button type="button" data-help-chip="${t}">${t}</button>`).join('')}</div><p id="help-search-status" class="search-status" role="status" aria-live="polite">검색어를 입력하거나 추천 항목을 선택해 주세요.</p><div id="service-search-results" class="service-search-results">${others.map(serviceCard).join('')}</div></div></section><p class="help-disclaimer">현재 도움 목록은 기능 검증용 예시야. 실제 서비스 이용 가능 여부, 신청 자격, 의료기관 연락처는 연동되지 않았어.</p></div>`;}
 function support(){const s=pickService(state.supportSelected);return `<div class="support-detail"><button class="back-button" data-nav="help">${icon('back',19)} 서비스 선택으로 돌아가기</button><div class="eyebrow">도움 안내 · 시연용</div><h1 class="service-title">${s.name}</h1><p class="service-lead">${s.summary}</p><section class="support-steps"><h2>이렇게 확인해 주세요</h2><ol>${s.steps.map(x=>`<li>${x}</li>`).join('')}</ol></section><div class="note-block">${icon('info',20)}<span>시연용 안내이며 개인별 의료 조언, 정식 서비스 신청, 기관의 승인·제공 확정을 의미하지 않습니다.</span></div><button class="link-soft support-back" data-nav="help">다른 도움 찾기</button></div>`;}
 function clinician(){return `<div><button class="back-button" data-nav="today">${icon('back',19)} 환자 화면 돌아가기</button><div class="eyebrow">의료진 업무 · 시연용 미리보기</div><h1 class="hero-title">계획 검토와<br><em>환자에게 공개하기.</em></h1><p class="sublead">기능의 안전한 연결을 테스트하는 최소 화면이야. 로그인·전문가 검증·병원 시스템 연동은 구현하지 않았어.</p><section class="clinician-panel"><h3>가상 환자 · 이정희</h3><p>고령 근골격계 퇴원환자 · 일정 2건 · 행동 안내 3개</p><div class="clinician-row"><div><b>현재 환자 공개 상태</b><p>${state.published?'v'+state.version+'.0 가상 승인본 공개 중':'승인 계획 게시 철회됨'}</p></div><span class="tiny-pill">모의 상태</span></div><div class="clinician-row"><div><b>승인·발행 이후 변경 관리</b><p>버전이 바뀌면 환자 화면에 새로운 안내 버전으로 표시돼.</p></div><button class="primary" data-action="publish">${state.published?'수정안 승인·발행':'다시 승인·발행'}</button></div><div class="clinician-row"><div><b>게시 철회 시나리오</b><p>환자 모드에 예전 계획을 최신 안내처럼 보여주지 않아.</p></div><button class="danger-button" data-action="withdraw" ${!state.published?'disabled':''}>게시 철회 시연</button></div></section><div class="note-block">${icon('info',20)}<span>실제 병원 승인 절차가 아니며 모의 상태전환만 작동해. 환자에게 보이는 자료도 가상 데이터야.</span></div></div>`}
 function blocked(){return `<div class="blocked"><div class="eyebrow">안내 확인 필요</div><h2>현재 공개된 퇴원 계획이 없어요.</h2><p>모의 의료진이 게시를 철회한 상태예요. 오래된 계획을 그대로 보여주지 않도록 안내를 가렸어.</p>${previewMode?`<div class="action-row"><button class="primary" data-action="clinician">의료진 시연 화면 ${icon('chev',17)}</button></div>`:''}</div>`}
 function runHelpSearch(query){state.helpQuery=query;const term=query.trim().toLowerCase();const list=document.querySelector('#service-search-results');const status=document.getElementById('help-search-status');if(!list||!status)return;const quick=['hospital','warning','mobility','appointment'];const matched=serviceCatalog.filter(x=>(x.name+' '+x.summary+' '+x.keywords).toLowerCase().includes(term));const results=term?matched:serviceCatalog.filter(x=>!quick.includes(x.id));list.innerHTML=results.length?results.map(serviceCard).join(''):'<div class="search-empty">일치하는 항목이 없어요. 다른 검색어를 사용하거나 퇴원 안내문에 적힌 담당 의료기관에 문의해 주세요.</div>';status.textContent=term?`${results.length}개의 관련 안내를 찾았어요.`:'아래에서 다른 도움을 선택할 수 있어요.';}
function focusMain(){const node=app.querySelector('#main-content');if(node){node.focus({preventScroll:true});}const frame=document.querySelector('#app-frame');frame.scrollIntoView({behavior:'instant',block:'start'});}
 function goto(view){if(view==='clinician'&&!previewMode)return;state.modal=null;closePdf();state.view=view;state.quizChoice=null;state.feedback=null;render();if(view==='help'&&state.helpSearchOpen){runHelpSearch(state.helpQuery)}focusMain()}
 document.addEventListener('submit',e=>{
  if(e.target.id==='demo-login'){e.preventDefault();const code=(new FormData(e.target).get('demoCode')||'').toString().trim().toUpperCase();state.loginCode=code;if(code===DEMO_CODE){state.codeVerified=true;state.authenticated=true;state.loginError='';state.view='today';render();focusMain();}else{state.loginError='체험용 코드를 확인해 주세요.';render();document.getElementById('demo-code')?.focus();}return;}
  if(e.target.id==='profile-form'){e.preventDefault();const formData=new FormData(e.target);const addr=String(formData.get('address')||'').trim(),phone=String(formData.get('contact')||'').trim();if(!addr||!phone||addr.length>120||phone.length>50){state.notice='주소와 연락처를 확인해 주세요.';render();return;}if(addr===state.profile.address&&phone===state.profile.contact){state.editing=false;state.profileDraft=null;state.notice='변경된 정보가 없어요.';render();return;}state.profileDraft={address:addr,contact:phone};overlayReturnFocus='#profile-form button[type=submit]';state.modal='save';render();document.querySelector('.modal-panel [data-action=modal-cancel]')?.focus();return;}
 });
 document.addEventListener('keydown',e=>{if(e.key==='Tab'&&(state.modal||state.pdfOpen)){const container=document.querySelector(state.pdfOpen?'.pdf-panel':'.modal-panel');const focusable=Array.from(container?.querySelectorAll('button:not([disabled]),a[href],input:not([disabled])')||[]);if(focusable.length){const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}if(e.key==='Escape'&&(state.modal||state.pdfOpen)){e.preventDefault();closeOverlay();}});
 document.addEventListener('click',e=>{
  const btn=e.target.closest('button');if(!btn)return;
  if(btn.dataset.preview){if(!previewMode)return;state.preview=btn.dataset.preview;render();return;}
  if(btn.dataset.nav){if(!state.authenticated)return;state.notice='';goto(btn.dataset.nav);return;}
  if(btn.dataset.detail){if(!state.authenticated||!state.published)return;state.selected=btn.dataset.detail;goto('detail');return;}
  if(btn.dataset.serviceId){if(!state.authenticated||!state.published)return;const s=pickService(btn.dataset.serviceId);if(s.route==='print'){goto('today');window.print();return;}if(s.route==='schedule'||s.route==='overview'){goto(s.route);return;}if(s.route==='mobility'||s.route==='meds'){state.selected=s.route;goto('detail');return;}state.supportSelected=s.id;goto('support');return;}
  if(btn.dataset.choice!==undefined){if(state.feedback!==null)return;state.quizChoice=Number(btn.dataset.choice);render();return;}
  if(btn.dataset.helpChip!==undefined){const q=btn.dataset.helpChip;const input=document.querySelector('[data-help-search]');if(input){input.value=q;runHelpSearch(q);input.focus();}return;}
  const a=btn.dataset.action;if(!a)return;
  if(!state.authenticated&&!['login-enter','login-back','font'].includes(a))return;
  if(!state.published&&['edit-start','modal-save','transfer-open','modal-transfer','pdf-open','quiz-start','quiz-check'].includes(a))return;
  if(a==='login-enter'){if(!state.codeVerified)return;state.authenticated=true;state.loginError='';state.view='today';render();focusMain();return;}
  if(a==='login-back'){state.codeVerified=false;state.loginCode='';render();return;}
  if(a==='logout'){state.authenticated=false;state.codeVerified=false;state.loginCode='';state.notice='';state.view='today';state.modal=null;closePdf();render();return;}
  if(a==='edit-start'){state.profileDraft={...state.profile};state.editing=true;state.notice='';render();return;}
  if(a==='edit-cancel'){state.profileDraft=null;state.editing=false;state.notice='';render();return;}
  if(a==='modal-cancel'){closeOverlay();return;}
  if(a==='modal-save'){
   if(state.modal!=='save'||!state.profileDraft)return;
   const next={profile:{...state.profileDraft},revision:state.savedRevision+1,lastRequest:null};
   if(!demoRepository.persist(next)){state.modal=null;state.notice='브라우저에 저장하지 못했어요. 입력 내용을 보관한 뒤 저장 공간과 다른 탭의 변경을 확인해 주세요.';render();document.querySelector('#address')?.focus();return;}
   state.profile=next.profile;state.profileDraft=null;state.editing=false;state.savedRevision=next.revision;state.transferStatus='none';state.lastRequest=null;state.modal=null;
   state.notice='주소·연락처가 이 브라우저에 저장됐어요. 연관 기관에는 아직 전송되지 않았습니다.';render();focusMain();return;
  }
  if(a==='transfer-open'){if(!state.savedRevision||state.editing||state.transferStatus==='requested')return;state.notice='';state.transferConsent=false;overlayReturnFocus='[data-action=transfer-open]';state.modal='transfer';render();document.querySelector('.modal-panel [data-action=modal-cancel]')?.focus();return;}
  if(a==='modal-transfer'){
   if(state.modal!=='transfer'||!state.savedRevision||state.editing||state.transferStatus==='requested')return;
   const consent=document.querySelector('#transfer-consent');if(!consent?.checked){document.querySelector('.consent-row')?.classList.add('input-error');return;}
   const request={requestId:'DEMO-'+String(state.savedRevision).padStart(4,'0'),revision:state.savedRevision,createdAt:new Date().toISOString(),status:'LOCAL_ONLY'};
   if(!demoRepository.persist({profile:state.profile,revision:state.savedRevision,lastRequest:request})){state.notice='요청 기록을 저장하지 못했어요. 실제 기관으로 전송되지 않았습니다.';closeOverlay();return;}
   state.lastRequest=request;state.transferStatus='requested';state.notice='업데이트 요청을 이 브라우저에 기록했어요. 실제 기관으로 전송되지 않았습니다.';closeOverlay();return;
  }
  if(a==='pdf-open'){
   if(state.version!==1||state.selected!=='mobility')return;
   try{if(!state.pdfUrl)state.pdfUrl=createDemoPdfUrl();state.pdfPreviewError=false;state.pdfOpen=true;overlayReturnFocus='[data-action=pdf-open]';render();document.querySelector('.close-pdf')?.focus();}
   catch{closePdf();state.notice='PDF를 열지 못했어요. 브라우저 설정을 확인한 뒤 다시 시도해 주세요.';render();document.querySelector('[data-action=pdf-open]')?.focus();}return;
  }
  if(a==='pdf-close'){closeOverlay();return;}
  if(a==='font'){state.large=!state.large;const saved=demoRepository.saveLarge(state.large);if(!saved)state.notice='글자 크기를 이 브라우저에 저장하지 못했어요. 현재 화면에는 적용했어요.';render();document.querySelector(state.pdfOpen?'.close-pdf':state.modal?'.modal-panel [data-action=modal-cancel]':'.top-font')?.focus();return}
  if(a==='clinician'){if(!previewMode)return;goto('clinician');return}
  if(a==='reset'){if(!previewMode)return;if(!demoRepository.clear()){state.notice='초기화하지 못했어요. 저장 상태를 확인해 주세요.';render();return;}closePdf();state.helpSearchOpen=false;state.helpQuery='';state.supportSelected='hospital';state.view='today';state.selected='mobility';state.quizChoice=null;state.feedback=null;state.read={};state.published=true;state.version=1;state.planChanged=false;state.profile={...initialProfile};state.profileDraft=null;state.editing=false;state.notice='';state.transferStatus='none';state.savedRevision=0;state.lastRequest=null;state.modal=null;state.pdfOpen=false;render();focusMain();return;}
  if(a==='detail-back'){goto('detail');return;}
  if(a==='quiz-start'){goto('quiz');return;}
  if(a==='quiz-check'){if(state.quizChoice===null)return;const x=task(state.selected);state.feedback=state.quizChoice===x.answer?'correct':'incorrect';state.read[x.id]=true;render();return;}
  if(a==='quiz-done'){goto(state.feedback==='correct'?'today':'detail');return;}
  if(a==='publish'){if(!previewMode)return;const next={published:true,version:state.version+1,planChanged:true};if(!demoRepository.persistPlan(next)){state.notice='새 계획 상태를 저장하지 못했어요. 발행 상태를 변경하지 않았습니다.';render();return;}Object.assign(state,next);goto('today');return;}
  if(a==='withdraw'){if(!previewMode)return;state.published=false;if(!demoRepository.persistPlan({published:false,version:state.version,planChanged:state.planChanged}))state.notice='철회 상태를 저장하지 못했어요. 현재 화면은 차단했지만 새로고침 전 저장 상태를 확인해 주세요.';goto('today');return;}
  if(a==='print'){window.print();return;}
  if(a==='toggle-help-search'){state.helpSearchOpen=!state.helpSearchOpen;state.helpQuery='';render();if(state.helpSearchOpen){const input=document.querySelector('[data-help-search]');runHelpSearch('');input?.focus();}return;}
 });
 document.addEventListener('input',e=>{if(e.target.matches('[data-profile-field]')&&state.editing&&state.profileDraft){state.profileDraft[e.target.dataset.profileField]=e.target.value;}if(e.target.matches('[data-help-search]')){runHelpSearch(e.target.value);}});
 document.addEventListener('change',e=>{if(e.target.id==='transfer-consent')state.transferConsent=e.target.checked;});
 document.addEventListener('error',e=>{if(e.target.matches?.('.pdf-image')&&!state.pdfPreviewError){state.pdfPreviewError=true;render();document.querySelector('.close-pdf')?.focus();}},true);
 window.addEventListener('storage',e=>{if(e.key===PLAN_KEY||e.key===null){const plan=demoRepository.loadPlan();Object.assign(state,plan);state.modal=null;closePdf();render();}});
 window.addEventListener('pagehide',closePdf);
 render();
})();
